import ast, hashlib, json, pathlib, shlex, subprocess
paths = [pathlib.Path(name) for name in ["docs/evidence/2026-09-10-v1-05c2d4-bounded-executor-author.json","docs/evidence/2026-09-10-v1-05c2d4-executor-fix-admission-review.json","docs/evidence/2026-09-10-v1-05c2d4-executor-fix-tree-review.json"]]
assert len(paths) == 3
total = bodies = 0
def walk(value, label):
    global total, bodies
    if isinstance(value, dict):
        for key, child in value.items():
            if isinstance(child, str) and (key == "command" or key.endswith("_command")):
                total += 1
                checked = subprocess.run(["bash", "-n"], input=child, text=True, capture_output=True)
                assert checked.returncode == 0, (label, key, checked.stderr)
                if "<<'PY'" in child:
                    body = child.split("\n", 1)[1].rsplit("\nPY", 1)[0]
                    ast.parse(body)
                    bodies += 1
                else:
                    tokens = shlex.split(child)
                    for pos, token in enumerate(tokens):
                        if token == "-c" and pos and tokens[pos-1] in ("python", "python3"):
                            ast.parse(tokens[pos+1])
                            bodies += 1
            walk(child, label + "." + key)
    elif isinstance(value, list):
        for pos, child in enumerate(value):
            walk(child, label + "[" + str(pos) + "]")
out = []
for path in paths:
    raw = path.read_bytes()
    data = json.loads(raw)
    walk(data, str(path))
    out.append({"path": str(path), "sha256": hashlib.sha256(raw).hexdigest(), "keys": list(data)})
print(json.dumps({"documents": out, "command_fields": total, "python_bodies": bodies}, sort_keys=True))
